/** One month of the Current Affairs Capsule (generated by scripts/current-affairs/build.ts). */
export type CapsuleMonth = {
  month: string; // YYYY-MM
  label: string; // "October 2025"
  /** Month still in progress when generated. */
  partial: boolean;
  generatedAt: string;
  headlines: Record<Source, number>;
  facts: MonthFacts;
  quiz: Mcq[];
};

